// Turn the config into one search job per query (and per format if searchType = both).
const cfg = $('Set Monitor Config').first().json;

const queries = String(cfg.queries || '')
  .split('\n')
  .map(q => q.trim())
  .filter(q => q.length > 0);

if (queries.length === 0) {
  throw new Error('No search queries configured. Add at least one line to "queries" in "Set Monitor Config".');
}

const allowedWindows = ['hour', 'today', 'week', 'month', 'year'];
const uploadDate = allowedWindows.includes(cfg.uploadDate) ? cfg.uploadDate : 'today';

const types = cfg.searchType === 'both'
  ? ['video', 'shorts']
  : [cfg.searchType === 'shorts' ? 'shorts' : 'video'];

return queries.flatMap(query =>
  types.map(searchType => ({ json: { query, searchType, uploadDate } }))
);

// Runs once per loop iteration (one query). The HTTP node replaces the item with the
// raw API body and may return several pages, so we re-attach the query here.
// Always return at least one item, otherwise the loop stops early and skips the remaining queries.
const job = $('Loop Over Queries').first().json;
const out = [];

for (const page of $input.all()) {
  const body = page.json || {};
  if (!Array.isArray(body.results)) {
    return [{
      json: {
        _kind: 'error',
        query: job.query,
        searchType: job.searchType,
        message: 'Unexpected response (no results array): ' + JSON.stringify(body).slice(0, 200)
      }
    }];
  }
  for (const post of body.results) {
    out.push({ json: { _kind: 'video', query: job.query, searchType: job.searchType, ...post } });
  }
}

if (out.length === 0) {
  out.push({ json: { _kind: 'empty', query: job.query, searchType: job.searchType } });
}
return out;

// Convert a failed request into a marker item so the loop continues
// and all failures are reported together in one Telegram message.
const job = $('Loop Over Queries').first().json;
const err = $input.first().json.error;
const message = (err && (err.message || err.description)) || (typeof err === 'string' ? err : JSON.stringify(err || {}));

return [{
  json: {
    _kind: 'error',
    query: job.query,
    searchType: job.searchType,
    message: String(message).slice(0, 300)
  }
}];

// Merge all search results, drop what is already in the sheet, apply filters,
// and produce one summary item: { rows (for Sheets), alerts (for Telegram), errors, stats }.
const cfg = $('Set Monitor Config').first().json;
const items = $input.all().map(i => i.json);

const list = s => String(s || '').split(/[,\n]/).map(x => x.trim().toLowerCase()).filter(Boolean);
const excludeWords = list(cfg.excludeKeywords);
const watchlist = list(cfg.watchlistChannels);
const blocklist = list(cfg.blockedChannels);
const maxAgeMs = Number(cfg.maxAgeHours || 48) * 3600 * 1000;
const strict = cfg.strictTitleMatch === true || cfg.strictTitleMatch === 'true';
const now = Date.now();

// Video IDs already logged. The sheet is the single source of truth, so dedup
// also works on manual test runs and survives re-imports of the workflow.
const known = new Set(
  $('Read Logged Videos').all()
    .map(r => String((r.json && r.json['Video ID']) || '').replace(/^'/, '').trim())
    .filter(Boolean)
);

const videoIdFromUrl = url => {
  try {
    const u = new URL(url);
    if (u.hostname.includes('youtu.be')) return u.pathname.slice(1) || null;
    if (u.searchParams.get('v')) return u.searchParams.get('v');
    const m = u.pathname.match(/\/(shorts|live|embed)\/([^/?#]+)/);
    if (m) return m[2];
  } catch (e) { /* fall through */ }
  return null;
};

// Cells are written with USER_ENTERED so the thumbnail formula renders.
// Neutralise any text that Sheets would otherwise evaluate as a formula.
const safe = v => {
  const s = v === null || v === undefined ? '' : String(v);
  return /^[=+\-@]/.test(s) ? "'" + s : s;
};

const stats = { scanned: 0, alreadyLogged: 0, tooOld: 0, excluded: 0, blocked: 0, offTopic: 0 };
const errors = items.filter(i => i._kind === 'error').map(i => ({ query: i.query, searchType: i.searchType, message: i.message }));
const fresh = new Map();

for (const v of items.filter(i => i._kind === 'video')) {
  stats.scanned++;
  const id = videoIdFromUrl(v.url) || v.url;
  if (!id) continue;

  // Same video found by another query or page in this run: just record the extra query
  if (fresh.has(id)) {
    const f = fresh.get(id);
    if (!f.queries.includes(v.query)) f.queries.push(v.query);
    continue;
  }
  if (known.has(id)) { stats.alreadyLogged++; continue; }

  const title = String(v.caption || '');
  const titleLc = title.toLowerCase();
  const channel = String(v.author || '');
  const channelKeys = [channel.toLowerCase(), String(v.author_id || '').toLowerCase()].filter(Boolean);

  const publishedMs = Date.parse(v.posted_at);
  if (!isNaN(publishedMs) && now - publishedMs > maxAgeMs) { stats.tooOld++; continue; }
  if (channelKeys.some(k => blocklist.includes(k))) { stats.blocked++; continue; }
  if (excludeWords.some(w => titleLc.includes(w))) { stats.excluded++; continue; }
  if (strict) {
    const terms = v.query.toLowerCase().split(/\s+/).filter(t => t.length > 2);
    if (!terms.every(t => titleLc.includes(t))) { stats.offTopic++; continue; }
  }

  fresh.set(id, {
    id,
    title,
    channel,
    channelId: v.author_id || '',
    url: v.url,
    publishedAt: v.posted_at || '',
    format: (String(v.url).includes('/shorts/') || v.searchType === 'shorts') ? 'Short' : 'Video',
    watchlist: channelKeys.some(k => watchlist.includes(k)),
    queries: [v.query]
  });
}

const firstSeen = new Date().toISOString();
const ordered = [...fresh.values()].sort((a, b) => String(a.publishedAt).localeCompare(String(b.publishedAt)));

// Keys must match the header row of the "Videos" tab exactly
const rows = ordered.map(v => ({
  'Video ID': safe(v.id),
  'Title': safe(v.title),
  'Channel': safe(v.channel),
  'Channel ID': safe(v.channelId),
  'Format': v.format,
  'Published At': v.publishedAt,
  'First Seen At': firstSeen,
  'Matched Queries': safe(v.queries.join(', ')),
  'Video URL': v.url,
  'Channel URL': v.channelId ? 'https://www.youtube.com/channel/' + v.channelId : '',
  'Thumbnail': /^[A-Za-z0-9_-]{6,20}$/.test(v.id) ? '=IMAGE("https://i.ytimg.com/vi/' + v.id + '/mqdefault.jpg")' : '',
  'Watchlist': v.watchlist ? 'yes' : '',
  'Status': 'New'
}));

const alerts = ordered.map(v => ({
  title: v.title,
  channel: v.channel,
  url: v.url,
  format: v.format,
  publishedAt: v.publishedAt,
  queries: v.queries.join(', '),
  watchlist: v.watchlist
}));

return [{
  json: {
    rows,
    alerts,
    errors,
    stats,
    jobsChecked: $('Build Query List').all().length,
    knownBefore: known.size,
    isManual: $execution.mode === 'manual',
    telegramChatId: cfg.telegramChatId,
    sheetUrl: cfg.sheetUrl
  }
}];

