// Compose Telegram messages (HTML parse mode; titles and channel names are escaped,
// because YouTube titles regularly contain characters that break Markdown).
// Watchlist channels get an instant message each, everything else goes into a digest.
const s = $('Dedupe and Classify').first().json;
const chatId = s.telegramChatId;
const esc = t => String(t === null || t === undefined ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sheetLink = /^https?:\/\//.test(s.sheetUrl || '') ? `\n\n<a href="${esc(s.sheetUrl)}">Open log sheet</a>` : '';
const MAX_LEN = 3500;      // Telegram limit is 4096 chars
const MAX_LISTED = 40;     // keep the digest readable on a big first run
const messages = [];

// 1) Watchlist: one message per video, with link preview
for (const v of s.alerts.filter(a => a.watchlist)) {
  messages.push({
    chatId,
    preview: true,
    text: `🚨 <b>Watchlist channel posted</b>\n\n<b>${esc(v.title)}</b>\n${esc(v.channel)} · ${v.format}\nMatched: ${esc(v.queries)}\n\n${esc(v.url)}`
  });
}

// 2) Digest for everything else, grouped by matched query, split into chunks
const rest = s.alerts.filter(a => !a.watchlist);
if (rest.length > 0) {
  const groups = {};
  for (const v of rest.slice(0, MAX_LISTED)) (groups[v.queries] = groups[v.queries] || []).push(v);

  const header = `📺 <b>${rest.length} new YouTube video${rest.length === 1 ? '' : 's'}</b>`;
  const lines = [];
  for (const [q, vids] of Object.entries(groups)) {
    lines.push(`\n<b>🔎 ${esc(q)}</b>`);
    for (const v of vids) {
      lines.push(`• <a href="${esc(v.url)}">${esc(v.title || '(untitled)')}</a> — ${esc(v.channel)}${v.format === 'Short' ? ' (Short)' : ''}`);
    }
  }
  if (rest.length > MAX_LISTED) lines.push(`\n…and ${rest.length - MAX_LISTED} more in the sheet.`);

  let chunk = header;
  for (const line of lines) {
    if ((chunk + '\n' + line).length > MAX_LEN) {
      messages.push({ chatId, preview: false, text: chunk });
      chunk = header + ' (cont.)';
    }
    chunk += '\n' + line;
  }
  messages.push({ chatId, preview: false, text: chunk + sheetLink });
}

// 3) One combined warning for all failed searches
if (s.errors.length > 0) {
  const lines = s.errors.map(e => `• "${esc(e.query)}" (${e.searchType}): ${esc(e.message)}`);
  messages.push({
    chatId,
    preview: false,
    text: `⚠️ <b>${s.errors.length} of ${s.jobsChecked} RecentReborn search${s.jobsChecked === 1 ? '' : 'es'} failed</b>\n\n${lines.join('\n')}\n\nCheck the API key credential and your search quota.`
  });
}

// 4) Manual test run with nothing to report: confirm the pipeline works
if (messages.length === 0 && s.isManual) {
  const st = s.stats;
  messages.push({
    chatId,
    preview: false,
    text: `✅ <b>Test run complete</b> — no new videos.\n\nSearches: ${s.jobsChecked}\nResults scanned: ${st.scanned}\nAlready logged: ${st.alreadyLogged}\nFiltered: ${st.tooOld} too old, ${st.excluded} excluded, ${st.blocked} blocked, ${st.offTopic} off-topic\nVideos in sheet: ${s.knownBefore}${sheetLink}`
  });
}

return messages.map(m => ({ json: m }));
